#Requires -Version 5.1
param([Parameter(Mandatory=$true)][string]$MartRoot,[string]$InstallDirectory="",[int]$Port=8013)
$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
if(!$InstallDirectory){$InstallDirectory=Join-Path (Split-Path -Parent $PSScriptRoot) 'nids-analysis-runtime'}
$runtime=[IO.Path]::GetFullPath($InstallDirectory);$py=Join-Path $runtime '.venv\Scripts\python.exe';$source=Join-Path $runtime 'source';$static=Join-Path $runtime 'sites\class3';$p=$null;$tmp=[IO.Path]::GetTempPath();$id=[guid]::NewGuid().ToString('N');$stdout=Join-Path $tmp ('.class3-host-'+$id+'.out.log');$stderr=Join-Path $tmp ('.class3-host-'+$id+'.err.log');$deadline=[DateTime]::UtcNow.AddSeconds(20)
try{$p=Start-Process -FilePath $py -ArgumentList @('-s','-m','services.class3_local_api','--mart-root',('"{0}"' -f $MartRoot),'--static-root',('"{0}"' -f $static),'--host','127.0.0.1','--port',"$Port") -WorkingDirectory $source -PassThru -WindowStyle Hidden -RedirectStandardOutput $stdout -RedirectStandardError $stderr
while([DateTime]::UtcNow -lt $deadline){if($p.HasExited){$tail=(Get-Content -LiteralPath $stderr -Tail 20 -ErrorAction SilentlyContinue) -join "`n";throw "Class 3 host exited before readiness: $tail"};try{$r=[Net.WebRequest]::Create("http://127.0.0.1:$Port/api/healthz").GetResponse();if([int]$r.StatusCode -eq 200){$r.Close();break}}catch{};Start-Sleep -Milliseconds 250};if([DateTime]::UtcNow -ge $deadline){throw 'Class 3 host readiness timeout after 20 seconds'}
&$py -s -c "import json,urllib.request,urllib.parse; base='http://127.0.0.1:$Port'; get=lambda p: urllib.request.urlopen(base+p,timeout=10).read(); assert b'<html' in get('/').lower(); assert b'<html' in get('/deep-link').lower(); assert json.loads(get('/api/healthz'))['service_mode']=='local_internal_only'; assert json.loads(get('/api/v1/status'))['public_release_policy']=='not_approved'; groups=json.loads(get('/api/v1/catalog/item-groups?limit=1'))['items']; assert groups; group=groups[0]['item_group_id']; body=json.dumps({'period_start':json.loads(get('/api/v1/status'))['period_start'],'period_end':json.loads(get('/api/v1/status'))['period_end'],'selections':[{'selection_type':'item_group','item_group_id':group}]}).encode(); req=urllib.request.Request(base+'/api/v1/comparisons',data=body,headers={'Content-Type':'application/json'}); assert json.loads(urllib.request.urlopen(req,timeout=10).read())['selections']; print('class3_http_rehearsal=ok')";if($LASTEXITCODE -ne 0){throw 'urllib rehearsal failed'}}finally{if($p -and -not $p.HasExited){Stop-Process -Id $p.Id -Force};foreach($f in @($stdout,$stderr)){if($f -and (Test-Path -LiteralPath $f)){Remove-Item -LiteralPath $f -Force}}}
